 35→    35→export const loader = async ({ request }: LoaderFunctionArgs) => {
 36→    36→  const { session, admin } = await authenticate.admin(request);
 37→    37→  const shop = session.shop;
 38→    38→
 39→    39→  let config = await db.widgetConfig.findUnique({ where: { shop } });
 40→    40→
 41→    41→  if (!config) {
 42→    42→    config = await db.widgetConfig.create({ data: { shop } });
 43→    43→  }
 44→    44→
 45→    45→  const subscription = await getShopSubscription(shop);
 46→    46→
 47→    47→  return { config, subscription };
 48→    48→};
