391→function buildWidgetCss(wid: string, cfg: WidgetConfig): string {
392→  const style = cfg.widgetStyle || "minimal";
393→  const baseCss =
394→    style === "bold" ? buildBoldCss(wid, cfg) :
395→    style === "card" ? buildCardCss(wid, cfg) :
396→    buildMinimalCss(wid, cfg);
397→  return baseCss + scopeAdminCss(cfg.customCss, wid);
398→}
